const start = new Date($input.item.json['Start Date']);
const end = new Date($input.item.json['End Date']);
const days = Math.ceil((end - start) / (1000*60*60*24)) + 1;
const employee = $input.item.json['Employee Name'];
const email = $input.item.json['Employee Email'];
const type = $input.item.json['Leave Type'];
const reason = $input.item.json['Reason'] || 'Not specified';
return [{ json: { employee, email, type, reason, start_date: $input.item.json['Start Date'], end_date: $input.item.json['End Date'], days, request_id: 'LR-' + Date.now() } }];

